// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IIncome {
    function owner() external view returns (address);
    function blacklistAddress(address account, bool value) external;
    function _isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Define a target address to blacklist (using a dummy contract address)
        address targetToBlacklist = address(0x1234567890123456789012345678901234567890);

        // First, let's get the current owner
        IIncome income = IIncome(TARGET);
        address owner = income.owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Call blacklistAddress to blacklist the target
        income.blacklistAddress(targetToBlacklist, true);

        vm.stopPrank();

        // Verify the address is now blacklisted
        bool isBlacklisted = income._isBlacklisted(targetToBlacklist);
        assertEq(isBlacklisted, true, "Target address should be blacklisted");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

